-- Generated by tools/runtime/generate-delivery-snapshot-migration.ts.
-- Local delivery closure only. No production activation; preserve immutable evidence on rollback.
SET search_path=bitpos,public;
CREATE TABLE quote_delivery_snapshots(
 merchant_id uuid NOT NULL,quote_id uuid NOT NULL,branch_id uuid NOT NULL,account_id uuid NOT NULL REFERENCES mobile_accounts,address_id uuid NOT NULL,address_version bigint NOT NULL CHECK(address_version>0),policy_version_id uuid NOT NULL,
 zone_version_id uuid,recipient_name text NOT NULL,phone text NOT NULL,address_text text NOT NULL,instructions text NOT NULL,
 origin_latitude_e7 integer NOT NULL CHECK(abs(origin_latitude_e7::bigint)<=900000000),origin_longitude_e7 integer NOT NULL CHECK(abs(origin_longitude_e7::bigint)<=1800000000),latitude_e7 integer NOT NULL CHECK(abs(latitude_e7::bigint)<=900000000),longitude_e7 integer NOT NULL CHECK(abs(longitude_e7::bigint)<=1800000000),
 currency text NOT NULL CHECK(currency IN('USD','USDG')),decimals smallint NOT NULL CHECK(decimals IN(2,4,6)),delivery_minor bigint NOT NULL CHECK(delivery_minor>=0),service_minor bigint NOT NULL CHECK(service_minor>=0),merchant_minor bigint NOT NULL CHECK(merchant_minor>=0),driver_minor bigint NOT NULL CHECK(driver_minor>=0),platform_minor bigint NOT NULL CHECK(platform_minor>=0),fixture boolean NOT NULL,
 PRIMARY KEY(merchant_id,quote_id),FOREIGN KEY(merchant_id,quote_id) REFERENCES order_quotes(merchant_id,id),FOREIGN KEY(merchant_id,branch_id,policy_version_id) REFERENCES delivery_policy_versions(merchant_id,branch_id,id),
 FOREIGN KEY(account_id,address_id) REFERENCES mobile_addresses(account_id,id),CHECK(delivery_minor+service_minor=merchant_minor+driver_minor+platform_minor)
);
CREATE TABLE food_shipments(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid NOT NULL,order_id uuid NOT NULL,quote_id uuid NOT NULL,account_id uuid NOT NULL REFERENCES mobile_accounts,
 state text NOT NULL CHECK(state IN('WAITING_MERCHANT','WAITING_PAYMENT','READY_FOR_DISPATCH','OFFERING','ASSIGNED','AT_PICKUP','PICKED_UP','AT_DROPOFF','DELIVERED','CANCELLED','FAILED','INCIDENT')),
 version bigint NOT NULL DEFAULT 1 CHECK(version>0),generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),active_assignment_id uuid,event_sequence bigint NOT NULL DEFAULT 0 CHECK(event_sequence>=0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(merchant_id,order_id),UNIQUE(id,generation),FOREIGN KEY(merchant_id,order_id) REFERENCES online_food_orders(merchant_id,order_id),FOREIGN KEY(merchant_id,quote_id) REFERENCES quote_delivery_snapshots(merchant_id,quote_id)
);
CREATE FUNCTION draft067_delivery_request_hash(account uuid,branch uuid,items jsonb,delivery quote_delivery_snapshots) RETURNS text
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog,bitpos,pg_temp AS $$
 SELECT encode(sha256(convert_to(jsonb_build_array('bitpos.delivery.quote.v1',
  configured_request_hash(account,branch,items),to_jsonb(delivery))::text,'UTF8')),'hex')
$$;
CREATE FUNCTION draft067_delivery_hash(merchant uuid,quote uuid,items jsonb) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
 SELECT draft067_delivery_request_hash(q.source_account_id,q.source_branch_id,items,d)
 FROM order_quotes q JOIN quote_delivery_snapshots d ON d.merchant_id=q.merchant_id AND d.quote_id=q.id
 WHERE q.merchant_id=merchant AND q.id=quote
$$;
CREATE OR REPLACE FUNCTION assert_configured_quote(merchant uuid,quote uuid) RETURNS void
LANGUAGE plpgsql SET search_path=bitpos,pg_temp AS $$
DECLARE q order_quotes%ROWTYPE;d quote_configured_food%ROWTYPE;expected jsonb;delivery quote_delivery_snapshots;price catalog_price_versions;fee numeric;total numeric;
BEGIN
 SELECT * INTO STRICT q FROM order_quotes WHERE merchant_id=merchant AND id=quote;
 SELECT * INTO d FROM quote_configured_food WHERE merchant_id=merchant AND quote_id=quote;
 IF q.origin_kind<>'online' THEN IF FOUND THEN RAISE EXCEPTION 'ROUTED_CONFIGURED_EVIDENCE' USING ERRCODE='23514';END IF;RETURN;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'MISSING_CONFIGURED_QUOTE' USING ERRCODE='23514';END IF;
 IF q.configured_food_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'UNCONFIGURED_QUOTE_VERSION' USING ERRCODE='23514';END IF;
 expected:=expected_configured_food(merchant,quote,d.items);
 IF q.authority->'serving'->>'kind'='delivery' THEN
  SELECT * INTO STRICT delivery FROM quote_delivery_snapshots WHERE merchant_id=merchant AND quote_id=quote;
  SELECT * INTO STRICT price FROM catalog_price_versions WHERE merchant_id=merchant AND id=q.price_version_id;
  fee:=delivery.delivery_minor+delivery.service_minor;
  total:=(expected->'total'->>'amountMinor')::numeric+fee;
  expected:=expected||jsonb_build_object('fees',configured_money(fee,price.currency,price.decimals),'total',configured_money(total,price.currency,price.decimals));
  IF d.snapshot IS DISTINCT FROM expected OR q.total_minor::text IS DISTINCT FROM expected->'total'->>'amountMinor'
  OR q.request_hash IS DISTINCT FROM draft067_delivery_hash(merchant,quote,d.items)
  THEN RAISE EXCEPTION 'DELIVERY_CONFIGURED_QUOTE_MISMATCH' USING ERRCODE='23514';END IF;
 ELSE
  IF d.snapshot IS DISTINCT FROM expected OR q.total_minor::text IS DISTINCT FROM expected->'total'->>'amountMinor'
  OR q.request_hash IS DISTINCT FROM configured_request_hash(q.source_account_id,q.source_branch_id,d.items)
  THEN RAISE EXCEPTION 'CONFIGURED_QUOTE_MISMATCH' USING ERRCODE='23514';END IF;
 END IF;
END $$;

CREATE FUNCTION draft067_assert_quote(merchant uuid,quote uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE q order_quotes;d quote_delivery_snapshots;p delivery_policy_versions;
BEGIN
 SELECT * INTO STRICT q FROM order_quotes WHERE merchant_id=merchant AND id=quote;
 SELECT * INTO d FROM quote_delivery_snapshots WHERE merchant_id=merchant AND quote_id=quote;
 IF q.origin_kind<>'online' OR q.authority->'serving'->>'kind' IS DISTINCT FROM 'delivery' THEN
  IF FOUND THEN RAISE EXCEPTION 'DELIVERY_QUOTE_IDENTITY' USING ERRCODE='23514'; END IF;
  RETURN;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_QUOTE_INCOMPLETE' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT p FROM delivery_policy_versions WHERE merchant_id=d.merchant_id AND branch_id=d.branch_id AND id=d.policy_version_id;
 IF (d.account_id,d.branch_id,d.currency,d.decimals,d.origin_latitude_e7,d.origin_longitude_e7,d.delivery_minor,d.service_minor,d.merchant_minor,d.driver_minor,d.platform_minor,d.fixture)
 IS DISTINCT FROM (q.source_account_id,q.source_branch_id,p.currency,p.decimals,p.origin_latitude_e7,p.origin_longitude_e7,p.delivery_minor,p.service_minor,p.merchant_minor,p.driver_minor,p.platform_minor,p.fixture)
 OR q.price_version_id IS DISTINCT FROM p.price_version_id
 OR d.latitude_e7 NOT BETWEEN p.south_e7 AND p.north_e7 OR d.longitude_e7 NOT BETWEEN p.west_e7 AND p.east_e7
 THEN RAISE EXCEPTION 'DELIVERY_QUOTE_IDENTITY' USING ERRCODE='23514'; END IF;
 -- Current address is checked at quote creation by the immediate guard below;
 -- later address edits must never invalidate this immutable historic quote.
 PERFORM assert_configured_quote(merchant,quote);
END $$;
CREATE FUNCTION draft067_snapshot_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE a mobile_addresses;
BEGIN
 SELECT * INTO STRICT a FROM mobile_addresses WHERE account_id=NEW.account_id AND id=NEW.address_id FOR SHARE;
 IF a.version IS DISTINCT FROM NEW.address_version OR a.archived
 OR (NEW.recipient_name,NEW.phone,NEW.address_text,NEW.instructions,NEW.latitude_e7,NEW.longitude_e7)
 IS DISTINCT FROM (a.recipient_name,a.phone,a.address_text,a.instructions,a.latitude_e7,a.longitude_e7)
 THEN RAISE EXCEPTION 'DELIVERY_ADDRESS_CHANGED' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER draft067_delivery_address BEFORE INSERT ON quote_delivery_snapshots FOR EACH ROW EXECUTE FUNCTION draft067_snapshot_insert();

CREATE FUNCTION draft067_shipment_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE q order_quotes;d quote_delivery_snapshots;a mobile_addresses;p branch_delivery_policies;
BEGIN
 SELECT * INTO STRICT q FROM order_quotes WHERE merchant_id=NEW.merchant_id AND id=NEW.quote_id;
 SELECT * INTO STRICT d FROM quote_delivery_snapshots WHERE merchant_id=NEW.merchant_id AND quote_id=NEW.quote_id;
 SELECT * INTO STRICT p FROM branch_delivery_policies WHERE merchant_id=NEW.merchant_id AND branch_id=d.branch_id FOR SHARE;
 SELECT * INTO STRICT a FROM mobile_addresses WHERE account_id=d.account_id AND id=d.address_id FOR SHARE;
 IF q.valid_until<=clock_timestamp() OR a.archived OR a.version<>d.address_version OR NOT p.enabled OR p.active_version_id<>d.policy_version_id
 OR NOT EXISTS(SELECT 1 FROM marketplace_branches WHERE merchant_id=NEW.merchant_id AND id=d.branch_id AND enabled AND delivery_enabled)
 THEN RAISE EXCEPTION 'DELIVERY_CONFIRMATION_SNAPSHOT_CHANGED_OR_EXPIRED' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER draft067_shipment_confirmation BEFORE INSERT ON food_shipments FOR EACH ROW EXECUTE FUNCTION draft067_shipment_insert();


CREATE FUNCTION delivery_quote_destination(merchant uuid,branch uuid,account uuid,quote uuid,address uuid,address_version bigint,policy uuid,price uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE result jsonb;
BEGIN
 IF merchant::text IS DISTINCT FROM current_setting('bitpos.merchant',true) OR account::text IS DISTINCT FROM current_setting('bitpos.mobile_account',true) THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='42501';END IF;
 SELECT jsonb_build_object('merchant_id',p.merchant_id,'quote_id',quote,'branch_id',p.branch_id,'account_id',a.account_id,'address_id',a.id,'address_version',a.version::text,'policy_version_id',p.id,'zone_version_id',NULL,'recipient_name',a.recipient_name,'phone',a.phone,'address_text',a.address_text,'instructions',a.instructions,'origin_latitude_e7',p.origin_latitude_e7,'origin_longitude_e7',p.origin_longitude_e7,'latitude_e7',a.latitude_e7,'longitude_e7',a.longitude_e7,'currency',p.currency,'decimals',p.decimals,'delivery_minor',p.delivery_minor::text,'service_minor',p.service_minor::text,'merchant_minor',p.merchant_minor::text,'driver_minor',p.driver_minor::text,'platform_minor',p.platform_minor::text,'fixture',p.fixture) INTO result
 FROM branch_delivery_policies h JOIN delivery_policy_versions p ON(p.merchant_id,p.branch_id,p.id)=(h.merchant_id,h.branch_id,h.active_version_id)
 JOIN marketplace_branches b ON(b.merchant_id,b.id)=(p.merchant_id,p.branch_id) JOIN mobile_addresses a ON a.account_id=account AND a.id=address
 WHERE h.merchant_id=merchant AND h.branch_id=branch AND h.enabled AND b.enabled AND b.delivery_enabled AND NOT a.archived AND a.version=address_version AND p.id=policy AND p.price_version_id=price
 AND a.latitude_e7 BETWEEN p.south_e7 AND p.north_e7 AND a.longitude_e7 BETWEEN p.west_e7 AND p.east_e7 FOR SHARE OF h,p,b,a;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION delivery_quote_destination(uuid,uuid,uuid,uuid,uuid,bigint,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION delivery_quote_destination(uuid,uuid,uuid,uuid,uuid,bigint,uuid,uuid) TO bitpos_app;
CREATE TRIGGER delivery_snapshot_immutable BEFORE UPDATE OR DELETE ON quote_delivery_snapshots FOR EACH ROW EXECUTE FUNCTION immutable_authority_row();
CREATE FUNCTION delivery_runtime_snapshot_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=bitpos,pg_temp AS $$
BEGIN PERFORM draft067_assert_quote(NEW.merchant_id,NEW.quote_id);RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER delivery_runtime_snapshot_complete AFTER INSERT ON quote_delivery_snapshots DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION delivery_runtime_snapshot_complete();
CREATE FUNCTION delivery_runtime_shipment_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=bitpos,pg_temp AS $$
DECLARE a order_authority;
BEGIN
 SELECT * INTO a FROM order_authority WHERE merchant_id=NEW.merchant_id AND order_id=NEW.order_id;
 IF NOT FOUND OR a.source_kind<>'online' OR a.serving_kind<>'delivery' OR a.quote_id IS DISTINCT FROM NEW.quote_id OR a.source_account_id IS DISTINCT FROM NEW.account_id
 OR NOT EXISTS(SELECT 1 FROM online_food_orders f WHERE f.merchant_id=NEW.merchant_id AND f.order_id=NEW.order_id AND f.account_id=NEW.account_id AND f.branch_id=a.source_branch_id)
 OR NEW.state<>'WAITING_MERCHANT' OR NEW.version<>1 OR NEW.generation<>0 OR NEW.event_sequence<>0 OR NEW.active_assignment_id IS NOT NULL
 THEN RAISE EXCEPTION 'INVALID_DELIVERY_SHIPMENT_ADMISSION' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER delivery_runtime_shipment_identity BEFORE INSERT ON food_shipments FOR EACH ROW EXECUTE FUNCTION delivery_runtime_shipment_identity();
REVOKE ALL ON FUNCTION delivery_runtime_snapshot_complete(),delivery_runtime_shipment_identity() FROM PUBLIC,bitpos_app;
CREATE FUNCTION delivery_runtime_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=bitpos,pg_temp AS $$
BEGIN
 PERFORM draft067_assert_quote(NEW.merchant_id,NEW.id);RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER delivery_runtime_quote_complete AFTER INSERT ON order_quotes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION delivery_runtime_complete();
CREATE FUNCTION delivery_runtime_admit_shipment() RETURNS trigger LANGUAGE plpgsql SET search_path=bitpos,pg_temp AS $$
DECLARE a order_authority;
BEGIN
 SELECT * INTO STRICT a FROM order_authority WHERE merchant_id=NEW.merchant_id AND order_id=NEW.order_id;
 IF a.serving_kind='delivery' THEN
  INSERT INTO food_shipments(merchant_id,order_id,quote_id,account_id,state) VALUES(NEW.merchant_id,NEW.order_id,a.quote_id,NEW.account_id,'WAITING_MERCHANT');
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER delivery_runtime_shipment AFTER INSERT ON online_food_orders FOR EACH ROW EXECUTE FUNCTION delivery_runtime_admit_shipment();
