GRANT EXECUTE ON FUNCTION draft067_delivery_request_hash(uuid,uuid,jsonb,quote_delivery_snapshots),draft067_delivery_hash(uuid,uuid,jsonb),draft067_assert_quote(uuid,uuid) TO bitpos_app;
